iconCss:
:root { --ball-puck-top: #2A2E36; --ball-puck-side: #16181D; --ball-puck-grip: #3D434E; --ball-puck-rim: #D5DCE5; --ball-puck-rim-w: 1.6; --ball-shine: rgba(255, 255, 255, 0.16); --ball-leather: #8A4B22; --ball-leather-edge: #4E2610; --ball-leather-rim: #8B93A3; --ball-lace: #F4EFE6; --ball-orange: #E8772E; --ball-orange-edge: #7A3510; --ball-orange-light: #F4A866; --ball-orange-deep: #D35F1E; --ball-seam: #2B1406; --ball-white: #F5F3EC; --ball-white-edge: #9AA0A8; --ball-stitch: #D7263D; }
.sport-icon .bi-puck-side { fill: var(--ball-puck-side); }
.sport-icon .bi-puck-top { fill: var(--ball-puck-top); stroke: var(--ball-puck-rim); stroke-width: var(--ball-puck-rim-w); }
.sport-icon .bi-puck-grip { stroke: var(--ball-puck-grip); }
.sport-icon .bi-puck-shine { fill: var(--ball-shine); }
.sport-icon .bi-rim { stroke: var(--ball-puck-rim); stroke-width: var(--ball-puck-rim-w); }
.sport-icon .bi-leather { fill: var(--ball-leather); stroke: var(--ball-leather-edge); }
.sport-icon .bi-leather-rim { stroke: var(--ball-leather-rim); }
.sport-icon .bi-stripe, .sport-icon .bi-lace { stroke: var(--ball-lace); }
.sport-icon .bi-basketball { fill: var(--ball-orange); stroke: var(--ball-orange-edge); }
.sport-icon .bi-seam { stroke: var(--ball-seam); }
.sport-icon .bi-wnba-white { fill: var(--ball-white); }
.sport-icon .bi-cbb-dark { fill: var(--ball-orange-deep); }
.sport-icon .bi-cbb-light { fill: var(--ball-orange-light); }
.sport-icon .bi-cbb-edge { stroke: var(--ball-orange-edge); }
.sport-icon .bi-wnba-orange { fill: var(--ball-orange); }
.sport-icon .bi-wnba-edge { stroke: var(--ball-orange-edge); }
.sport-icon .bi-baseball { fill: var(--ball-white); stroke: var(--ball-white-edge); }
.sport-icon .bi-stitch { stroke: var(--ball-stitch); }
